commit 9366061632346632f61eeb789260dd2bb59b6716
Author: loop-bench <loop-bench@localhost>
Date:   Fri Nov 6 15:17:59 2026 +0100

    fix(orchestrator): call onError for non-Error rejections

    Refs #95

    Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>

diff --git a/CHANGELOG.md b/CHANGELOG.md
index eab0af2..d3deb9f 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -24,6 +24,7 @@ package, not for somebody reading this repository's commit log.

 ### Fixed

+- `onError` now fires for every rejection inside a turn, not only one that is an `Error`. A provider or hook that rejects with a string, a plain object or `undefined` previously skipped `onError` while still rejecting to the caller, so a failure counter or pager wired to the hook missed it. Such a value now reaches `onError` wrapped in an `Error` whose `message` is the string or its JSON form and whose `cause` is the original value; an `Error` still arrives as the same instance. The caller still receives the original rejection unchanged. **Migration note**: none needed — the hook keeps its `(session, error: Error)` signature, and it now also runs for these rejections, which it never saw before.
 - `onError` and `afterSession` hooks now fire when `beforeSession` throws, matching the guarantee the hook names imply. Previously, a throw from `beforeSession` escaped the `try`/`finally` block entirely, so neither hook ran. **Migration note**: if your `afterSession` hook assumed it would only be called after a full session turn, it will now also be called when `beforeSession` itself fails — the hook can inspect the session to detect this case (no entries beyond the initial user message will have been processed).

 ## [0.3.0] - 2026-09-29
diff --git a/src/orchestration/chatOrchestrator.ts b/src/orchestration/chatOrchestrator.ts
index 8defbd2..059a91d 100644
--- a/src/orchestration/chatOrchestrator.ts
+++ b/src/orchestration/chatOrchestrator.ts
@@ -147,9 +147,7 @@ export function createChatOrchestrator(

         if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
       } catch (error) {
-        if (hooks?.onError && error instanceof Error) {
-          await hooks.onError(session, error);
-        }
+        if (hooks?.onError) await hooks.onError(session, asError(error));
         throw error;
       } finally {
         // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
@@ -332,6 +330,20 @@ function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | u
   };
 }

+// The hook is typed against Error, so anything else is wrapped with the raw value kept as its cause.
+function asError(reason: unknown): Error {
+  return reason instanceof Error ? reason : new Error(rejectionMessage(reason), {cause: reason});
+}
+
+function rejectionMessage(reason: unknown): string {
+  if (typeof reason === 'string') return reason;
+  try {
+    return JSON.stringify(reason) ?? String(reason);
+  } catch {
+    return String(reason);
+  }
+}
+
 // A store outage is not a reason to fail the turn the customer already received.
 async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
   if (!store?.save) return;
UPTODATE

